ion":"1080P","duration":10}}''', '{"payloadKeys": ["prompt", "negative_prompt", "first_frame", "reference_image", "reference_video", "resolution", "ratio", "duration", "prompt_extend", "watermark", "seed"]}'::jsonb, '', FALSE, 1000),
  ('gmi/seedance-2.0-fast', 'seedance-2-0-fast-260128', 'gmi-cloud', 'Seedance', 'Seedance 2.0 Fast', 'Next-gen video generation supporting text, first/last frame images, reference images/videos/audios. 4-15s duration up to 1080p.', 'Video', '$0.022 per second', '{"raw": "$0.022 / second", "usd": 0.022, "credits": 4}'::jsonb, 'request_queue', 'video', 'text-to-video', 'generation', ARRAY['prompt','duration','resolution','ratio','seed','watermark','generate_audio','web_search','first_frame','last_frame','reference_images','reference_videos','reference_audios','image','image_url']::text[], ARRAY['prompt','duration','resolution','ratio','seed','watermark','generate_audio','web_search','first_frame','last_frame','reference_images','reference_videos','reference_audios']::text[], ARRAY[]::text[], '{"duration": 5, "resolution": "720p", "ratio": "16:9", "watermark": false, "generate_audio": true, "web_search": false}'::jsonb, '[{"key": "resolution", "label": "Resolution", "type": "select", "defaultValue": "720p", "options": [{"label": "480p", "value": "480p"}, {"label": "720p", "value": "720p"}, {"label": "1080p", "value": "1080p"}]}, {"key": "ratio", "label": "Aspect Ratio", "type": "select", "defaultValue": "16:9", "options": [{"label": "16:9", "value": "16:9"}, {"label": "4:3", "value": "4:3"}, {"label": "1:1", "value": "1:1"}, {"label": "3:4", "value": "3:4"}, {"label": "9:16", "value": "9:16"}, {"label": "21:9", "value": "21:9"}, {"label": "adaptive", "value": "adaptive"}]}, {"key": "duration", "label": "Duration (s)", "type": "number", "defaultValue": 5, "min": 4, "max": 15, "step": 1}, {"key": "generate_audio", "label": "Generate Audio", "type": "boolean", "defaultValue": true}, {"key": "watermark", "label": "Watermark", "type": "boolean", "defaultValue": false}]'::jsonb, ARRAY['seedance-2-0-fast-260128','seedance-2.0-fast']::text[], TRUE, 4, '~30s', 150, ARRAY['studio:video','kanvas:video']::text[], ARRAY['text-to-video','image-to-video']::text[], 'curl -X POST http